const join = (c = code) => {
  // v4.11: 首个实参可能是点击事件（onClick=${join}）——只接受字符串，否则回退到输入框的值。
  const raw = String(typeof c === 'string' ? c : (code ?? ''));
  // v4.0: 链接 → 按访客提交该服务器到清单；邀请码 → 先当前服务器，无结果再跨服轮询。
  if (window.__SP_JOIN && typeof window.__SP_JOIN.looksLikeLink === 'function' && window.__SP_JOIN.looksLikeLink(raw)) {
    submitLink(raw.trim());
    return;
  }
  const k = normalizeCode(raw);
  if (!CODE_RE.test(k)) { toast(`同盟密钥为 ${ROOM_CODE_LEN} 位字母或数字`, 'warn'); return; }
  run('join', async () => {
    try {
      await net.request('room.join', { code: k });
    } catch (err) {
      // 当前服务器没有该房 → 轮询其他服务器（复用 shell-join.js 的跨服探测）
      if (!err || err.code !== 'ROOM_NOT_FOUND'
        || !window.__SP_JOIN || typeof window.__SP_JOIN.resolveCode !== 'function') throw err;
      const r = await window.__SP_JOIN.resolveCode(k);
      const hit = r && (r.kind === 'single' ? r.entry
        : r.kind === 'conflict' && Array.isArray(r.entries) ? r.entries[0] : null);
      if (hit && hit.id && window.shell && typeof window.shell.joinOnOrigin === 'function') {
        window.shell.joinOnOrigin(hit.id, k);
        return;
      }
      toast((r && r.note) || '未找到该同盟密钥对应的房间', 'warn');
    }
  });
};
const submitLink = (raw) => {
  toast('正在提交服务器…');
  setTimeout(() => {
    const p = window.__SP_JOIN && typeof window.__SP_JOIN.submitServerLink === 'function'
      ? window.__SP_JOIN.submitServerLink(raw)
      : Promise.resolve({ ok: false, text: '当前版本不支持提交，请到 dl.jiangjiangze.icu/servers 提交' });
    Promise.resolve(p).then((x) => {
      if (x && x.ok) toast(String(x.text || '已提交，审核通过后会出现在服务器列表'), 'success');
      else toast(String((x && x.text) || '提交失败，请稍后重试'), 'warn');
    }).catch(() => toast('提交失败，请稍后重试', 'warn'));
  }, 50);
};

