const join = (c = code) => {
  // v4.12: 与大厅面板「邀请码」同一条路 —— resolveCode（目录 presence + 清单内各服 /api/rooms
  // 并发探测，本服在内，按延迟排序）→ 命中即加入：本服命中直接 room.join（不重载），跨服命中
  // 走 joinOnOrigin(id, code)（切服带码，重载后自动进房）；无命中/网页版退回本服 room.join，
  // 错误照常由游戏自身提示。
  const raw = String(typeof c === 'string' ? c : (code ?? ''));
  // 链接 → 按访客提交该服务器到清单（v4.0 语义原样保留）
  if (window.__SP_JOIN && typeof window.__SP_JOIN.looksLikeLink === 'function' && window.__SP_JOIN.looksLikeLink(raw)) {
    submitLink(raw.trim());
    return;
  }
  const k = normalizeCode(raw);
  if (!CODE_RE.test(k)) { toast(`同盟密钥为 ${ROOM_CODE_LEN} 位字母或数字`, 'warn'); return; }
  if (!window.__SP_JOIN || typeof window.__SP_JOIN.resolveCode !== 'function') {
    run('join', () => net.request('room.join', { code: k })); // 老壳：保持本服加入
    return;
  }
  run('join', async () => {
    const r = await window.__SP_JOIN.resolveCode(k);
    const entries = r && r.kind === 'conflict' && Array.isArray(r.entries) ? r.entries
      : (r && r.kind === 'single' && r.entry ? [r.entry] : []);
    let myId = '';
    try {
      myId = String((window.shell && window.shell.currentServerId && window.shell.currentServerId()) || '');
    } catch (e) { myId = ''; }
    // 多命中：本服优先（免重载），否则取延迟最低的（resolveCode 已按 rtt 升序）
    const local = myId ? entries.filter((e) => e && e.id === myId)[0] : null;
    const hit = local || entries[0] || null;
    if (hit && hit.id && (!myId || hit.id !== myId) && window.shell && typeof window.shell.joinOnOrigin === 'function') {
      window.shell.joinOnOrigin(hit.id, k); // 跨服：切服带码
      return;
    }
    await net.request('room.join', { code: k }); // 本服 / 目录无结果 / 网页：直达，错误由游戏提示
  });
};

